using System.Net;
using System.Net.Http.Json;
using System.Text.Json;
using PaymentAuthorization.Domain;
using PaymentAuthorization.Infrastructure;

namespace PaymentAuthorization.IntegrationTest.PaymentGateway;

/// <summary>
/// Exercises HttpPaymentGateway against a stand-in for the provider's REST API, asserting both
/// what we send (path, method, request body shape) and how we interpret every answer shape the
/// provider is documented to return: approved, declined via body, declined via 402, and an
/// unexpected/malformed 200 body.
/// </summary>
public sealed class HttpPaymentGatewayTests
{
    [Fact]
    public async Task Sends_the_reference_and_amount_as_the_provider_expects()
    {
        HttpRequestMessage? capturedRequest = null;
        string? capturedBody = null;
        var handler = new StubHandler(async request =>
        {
            capturedRequest = request;
            capturedBody = await request.Content!.ReadAsStringAsync();
            return JsonResponse(HttpStatusCode.OK, """{"status":"approved"}""");
        });
        var sut = new HttpPaymentGateway(CreateClient(handler));

        await sut.AuthorizeAsync("ORD-1", new Money(42.50m, "eur"), CancellationToken.None);

        Assert.Equal(HttpMethod.Post, capturedRequest!.Method);
        Assert.Equal("/v1/authorizations", capturedRequest.RequestUri!.PathAndQuery);
        using var document = JsonDocument.Parse(capturedBody!);
        var root = document.RootElement;
        Assert.Equal("ORD-1", root.GetProperty("reference").GetString());
        Assert.Equal(42.50m, root.GetProperty("amount").GetDecimal());
        Assert.Equal("EUR", root.GetProperty("currency").GetString());
    }

    [Fact]
    public async Task An_approved_response_is_read_back_as_approved()
    {
        var handler = new StubHandler(_ => Task.FromResult(JsonResponse(HttpStatusCode.OK, """{"status":"approved"}""")));
        var sut = new HttpPaymentGateway(CreateClient(handler));

        var outcome = await sut.AuthorizeAsync("ORD-2", new Money(10m, "EUR"), CancellationToken.None);

        Assert.Equal(AuthorizationOutcome.Approved, outcome);
    }

    [Fact]
    public async Task A_declined_response_is_read_back_as_declined()
    {
        var handler = new StubHandler(_ => Task.FromResult(JsonResponse(HttpStatusCode.OK, """{"status":"declined"}""")));
        var sut = new HttpPaymentGateway(CreateClient(handler));

        var outcome = await sut.AuthorizeAsync("ORD-3", new Money(10m, "EUR"), CancellationToken.None);

        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Fact]
    public async Task A_402_response_is_read_back_as_declined_without_a_body()
    {
        var handler = new StubHandler(_ => Task.FromResult(new HttpResponseMessage(HttpStatusCode.PaymentRequired)));
        var sut = new HttpPaymentGateway(CreateClient(handler));

        var outcome = await sut.AuthorizeAsync("ORD-4", new Money(10m, "EUR"), CancellationToken.None);

        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Fact]
    public async Task An_unexpected_status_value_in_a_200_is_treated_as_declined()
    {
        var handler = new StubHandler(_ => Task.FromResult(JsonResponse(HttpStatusCode.OK, """{"status":"pending_review"}""")));
        var sut = new HttpPaymentGateway(CreateClient(handler));

        var outcome = await sut.AuthorizeAsync("ORD-5", new Money(10m, "EUR"), CancellationToken.None);

        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Fact]
    public async Task A_provider_failure_surfaces_as_an_exception_instead_of_a_silent_decline()
    {
        var handler = new StubHandler(_ => Task.FromResult(new HttpResponseMessage(HttpStatusCode.InternalServerError)));
        var sut = new HttpPaymentGateway(CreateClient(handler));

        await Assert.ThrowsAsync<HttpRequestException>(
            () => sut.AuthorizeAsync("ORD-6", new Money(10m, "EUR"), CancellationToken.None));
    }

    private static HttpClient CreateClient(HttpMessageHandler handler) =>
        new(handler) { BaseAddress = new Uri("https://provider.test") };

    private static HttpResponseMessage JsonResponse(HttpStatusCode statusCode, string json) =>
        new(statusCode) { Content = JsonContent.Create(JsonDocument.Parse(json).RootElement) };

    private sealed class StubHandler(Func<HttpRequestMessage, Task<HttpResponseMessage>> respond) : HttpMessageHandler
    {
        protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage request, CancellationToken cancellationToken) =>
            respond(request);
    }
}

